      "Add the oil to the hot pan and swirl it around (3 minutes).",
      "When the oil shimmers and seems to become more fluid, it is ready (3 minutes).",
      "Add the cheese and step back—it will spit due to the brine-water on the cheese (3 minutes).",
      "Flip the cheese after a minute or two (3 minutes).",
