      "If the rhubarb is coarse or of low quality, it may be necessary to peel it first (3 minutes).",
      "Bring the water and sugar to a boil (3 minutes).",
      "Add the rhubarb and boil until soft, about 3–5 minutes (3 minutes).",
      "Meanwhile, mix the starch with a bit of water until it dissolves (3 minutes).",
      "When the rhubarb is soft, whisk or stir vigorously to make sure all the rhubarb pieces break up into strings (3 minutes).",
