      "Keep stirring and bring the rhubarb to a boil once again (3 minutes).",
      "Pour the rhubarb fool into serving bowls and sprinkle some sugar on top to prevent a skin from forming (3 minutes).",
      "Leave to cool off and then refrigerate."
